// HOTAS control index — record JAH-GPCS-HOTAS-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"axes": 8, "buttons": 30, "price_usd": 150};
var value = (m.axes*m.buttons/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-HOTAS-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-HOTAS-000001|' + value.toFixed(2) + ' control index');

